class Kern:
    def __init__(self):
        self.plugins = {}

    def registriere(self, name, f):
        self.plugins[name] = f

    def ausfuehren(self, name, text):
        if name not in self.plugins:
            return "unbekannt"
        return self.plugins[name](text)

k = Kern()
k.registriere("gross", str.upper)
k.registriere("woerter",
    lambda t: len(t.split()))
print(k.ausfuehren("gross", "htl"))
print(k.ausfuehren("woerter", "a b c"))
print(k.ausfuehren("pdf", "x"))
# HTL
# 3
# unbekannt

def lesen(zeilen):
    for z in zeilen:
        yield z.strip()

def nur_fehler(zeilen):
    for z in zeilen:
        if z.startswith("ERROR"):
            yield z

def nummerieren(zeilen):
    for i, z in enumerate(zeilen, 1):
        yield f"{i}: {z}"

log = ["INFO start", "ERROR db",
       "INFO ok", "ERROR netz"]
for z in nummerieren(
        nur_fehler(lesen(log))):
    print(z)
# 1: ERROR db
# 2: ERROR netz

